// @param playbackSpeed = 1 (0.1..3)
let mixer;
function init() {
 mixer = new THREE.AnimationMixer(this);
 mixer.clipAction(this.animations[0]).play();
}
function update(event) { mixer.update(event.delta / 1000 * params.playbackSpeed); }

